  window.CampusDemoBookstoreStability=Object.freeze({COURSE_PRODUCTS:Object.freeze(Object.fromEntries(COURSE_PRODUCTS.map(product=>[product.id,product]))),readCourseCart,clearCourseCart,courseCount,courseSubtotal,courseItems,parseMoney,money,summaryRow,augmentCheckout,sync:queueSync});
