  function perItemMarkup(scope){const options=selected=>`<option value="USD" ${selected==='USD'?'selected':''}>USD</option><option value="BEACH" ${selected==='BEACH'?'selected':''}>BEACH</option>`;return `<div class="cb-per-item-allocation">${checkoutItems(scope).map(item=>{const selected=payment.itemCurrencies.get(item.key)||payment.basicCurrency;payment.itemCurrencies.set(item.key,selected);return `<div class="cb-per-item-currency-row"><span><strong>${esc(item.name)}</strong><small>${item.quantity} item${item.quantity===1?'':'s'} · ${money(item.lineTotal)}</small></span><select data-cb-pay-item="${esc(item.key)}">${options(selected)}</select></div>`;}).join('')}</div>`;}
