  function paymentCardMarkup(scope,value,signature){const totals=summaryValues(scope),options=selected=>`<option value="USD" ${selected==='USD'?'selected':''}>US Dollar (USD)</option><option value="BEACH" ${selected==='BEACH'?'selected':''}>BEACH</option>`;return `<section class="cb-checkout-card cb-payment-card" data-cb-payment-card data-cb-payment-signature="${esc(signature)}"><div class="cb-checkout-card-head"><div><h2>Payment</h2><p>Use the Campus Wallet linked to this Buddy account.</p></div><span>1 BEACH = $1.00</span></div><div class="cb-checkout-option-list"><label class="cb-checkout-option"><span><b>Payment currency</b><small>Choose a single currency for the order.</small></span><select data-cb-pay-basic>${options(payment.basicCurrency)}</select></label><div class="cb-wallet-balances">${walletBalanceMarkup(value)}</div><label class="cb-checkout-option cb-advanced-toggle-row"><span><b>Advanced payment <em>Optional</em></b><small>Split the order or choose a currency per item.</small></span><span class="cb-checkout-switch"><input type="checkbox" data-cb-pay-advanced ${payment.advanced?'checked':''}><i aria-hidden="true"></i></span></label></div>${payment.advanced?`<div class="cb-checkout-advanced-panel"><div class="cb-allocation-mode"><label><input type="radio" name="cbAllocation" value="split" data-cb-pay-mode ${payment.allocationMode==='split'?'checked':''}><span>Split Payment</span></label><label><input type="radio" name="cbAllocation" value="item" data-cb-pay-mode ${payment.allocationMode==='item'?'checked':''}><span>Per item</span></label></div>${payment.allocationMode==='split'?splitPanelMarkup(totals.total):perItemMarkup(scope)}</div>`:''}</section>`;}
  function enhanceCheckout(scope){const checkout=scope.querySelector('.cb-checkout-page');if(!checkout)return;const value=ensureBalances();if(!value)return;const column=checkout.querySelector('.cb-checkout-column');if(!column)return;const existing=column.querySelector('[data-cb-payment-card]'),signature=paymentSignature(scope,value);if(!existing)column.insertAdjacentHTML('beforeend',paymentCardMarkup(scope,value,signature));else if(existing.dataset.cbPaymentSignature!==signature)existing.outerHTML=paymentCardMarkup(scope,value,signature);const summary=checkout.querySelector('.cb-checkout-summary');if(!summary)return;let composition=summary.querySelector('[data-cb-payment-composition]');if(!composition){composition=document.createElement('div');composition.className='cb-payment-composition';composition.dataset.cbPaymentComposition='';summary.querySelector('.cb-place-order')?.insertAdjacentElement('beforebegin',composition);}if(composition)composition.innerHTML=`<strong>Campus Wallet payment</strong><span>${esc(allocationSummary(scope))}</span>`;const button=summary.querySelector('.cb-place-order'),total=summaryValues(scope).total;if(button){setText(button,`Pay ${money(total)} · Complete purchase`);const aria=`Pay ${money(total)} and complete purchase`;if(button.getAttribute('aria-label')!==aria)button.setAttribute('aria-label',aria);}const note=summary.querySelector(':scope > p');if(note)setText(note,'Demo purchase · funds are deducted from the linked Campus Wallet.');}
