  function commitWalletPayment(scope){if(committing)return false;const value=ensureBalances();if(!value)return false;const breakdown=paymentBreakdown(scope),unavailable=breakdown.find(item=>item.units>Number(value.balances[item.code]||0)+.000001);if(unavailable){toast(`Insufficient ${unavailable.code} balance. Choose another payment allocation or swap funds in Campus Wallet.`);return false;}committing=true;const total=summaryValues(scope).total,now=Date.now(),at=new Date(now).toLocaleString();breakdown.forEach((item,index)=>{value.balances[item.code]=Math.max(0,Math.round((Number(value.balances[item.code])-item.units)*100)/100);value.transactions.unshift({id:`BOOK-${now.toString(36).toUpperCase()}-${index+1}`,amount:-item.units,currency:item.code,label:'Campus Bookstore purchase',at,createdAt:now+index,kind:'purchase',merchant:'Campus Bookstore',orderTotalUsd:Math.round(total*100)/100,paymentComposition:breakdown.map(part=>({currency:part.code,amount:part.units}))});});value.balance=Math.round(Number(value.balances.USD)*100)/100;persistSession(value);payment.itemCurrencies.clear();committing=false;return true;}
